#' CFA
#'
#' Confirmatory factor analysis of one factor, several correlated factors, or 
#' a second-order structure: fit indices, standardized loadings, factor 
#' correlations, reliability (alpha, omega, AVE), and a comb plot. Handles 
#' ordinal items natively via WLSMV.
#' 
#'
#' @examples
#' \donttest{
#' data('wizdata', package = 'psyWiz')
#' # resCov has no default when called from R: pass list() for none
#' psyWiz::plainCfa(wizdata, run = TRUE, resCov = list(), factors = list(
#'     list(label = 'Trust', vars = c('trust1', 'trust2', 'trust3', 'trust4')),
#'     list(label = 'Stress', vars = c('stress1', 'stress2', 'stress3', 'stress4'))))
#'}
#' @param data the data as a data frame
#' @param factors a list of lists, each with a \code{label} (the factor name)
#'   and \code{vars} (the names of its items)
#' @param run \code{TRUE} or \code{FALSE} (default), fit the models; while
#'   \code{FALSE} only a summary of the plan is shown
#' @param type \code{'auto'} (default; ordinal variables are treated as
#'   ordinal, continuous ones as continuous), \code{'ordinal'} or
#'   \code{'continuous'}
#' @param estimator \code{'auto'} (default; MLR for continuous items, WLSMV
#'   for ordinal items), \code{'ML'}, \code{'MLR'}, \code{'MLM'},
#'   \code{'WLSMV'}, \code{'ULSMV'}, \code{'DWLS'} or \code{'ULS'}
#' @param missing \code{'auto'} (default; FIML for ML and MLR, pairwise
#'   deletion for ordinal items), \code{'listwise'}, \code{'fiml'} or
#'   \code{'pairwise'}
#' @param resCov a list of lists, each with \code{i1} and \code{i2}: pairs of
#'   items whose residuals may correlate
#' @param secondOrder \code{TRUE} or \code{FALSE} (default), let the factors
#'   (three or more) load on one second-order factor
#' @param higherName a string, the name of the second-order factor
#' @param showLoadings \code{TRUE} (default) or \code{FALSE}, show the
#'   loadings
#' @param showRel \code{TRUE} (default) or \code{FALSE}, show alpha, omega and
#'   AVE per factor
#' @param showCors \code{TRUE} (default) or \code{FALSE}, show the
#'   correlations between the factors
#' @param showMethods \code{TRUE} or \code{FALSE} (default), show each factor
#'   correlation as obtained from composite scores, corrected composites, the
#'   CFA and factor scores
#' @param showMi \code{TRUE} or \code{FALSE} (default), list the residual
#'   correlations and cross-loadings with the largest modification indices
#' @param miN an integer (default 10), how many to list
#' @param highlight \code{TRUE} or \code{FALSE} (default), highlight poor fit
#'   indices, weak loadings (below 0.40), and low reliability in red
#' @param showComb \code{TRUE} (default) or \code{FALSE}, draw the comb plot:
#'   one tooth per item, whose length is the variance the item shares with its
#'   factor
#' @param combThick \code{TRUE} or \code{FALSE} (default), make each tooth as
#'   thick as the item's observed variance is large
#' @param showPath \code{TRUE} or \code{FALSE} (default), draw the path
#'   diagram
#' @param pathNumbers \code{TRUE} (default) or \code{FALSE}, print the
#'   standardized loadings on the arrows
#' @param pathWidth \code{TRUE} (default) or \code{FALSE}, make the width of
#'   an arrow proportional to its loading
#' @param plotFit \code{'none'} (default), \code{'below'} or \code{'above'},
#'   print the model fit measures and estimator on the figure
#' @param showPlotGuide \code{TRUE} (default) or \code{FALSE}, show a short
#'   reading guide above each novel plot
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$loadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cors} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rel} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$methods} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mi} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$higher} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$resid} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$combDesc} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$comb} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$pathFig} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fit$asDF}
#'
#' \code{as.data.frame(results$fit)}
#'
#' @export
plainCfa <- function(
    data,
    factors = list(
                list(label="Factor 1", vars=list())),
    run = FALSE,
    type = "auto",
    estimator = "auto",
    missing = "auto",
    resCov,
    secondOrder = FALSE,
    higherName = "General",
    showLoadings = TRUE,
    showRel = TRUE,
    showCors = TRUE,
    showMethods = FALSE,
    showMi = FALSE,
    miN = 10,
    highlight = FALSE,
    showComb = TRUE,
    combThick = FALSE,
    showPath = FALSE,
    pathNumbers = TRUE,
    pathWidth = TRUE,
    plotFit = "none",
    showPlotGuide = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("plainCfa requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- plainCfaOptions$new(
        factors = factors,
        run = run,
        type = type,
        estimator = estimator,
        missing = missing,
        resCov = resCov,
        secondOrder = secondOrder,
        higherName = higherName,
        showLoadings = showLoadings,
        showRel = showRel,
        showCors = showCors,
        showMethods = showMethods,
        showMi = showMi,
        miN = miN,
        highlight = highlight,
        showComb = showComb,
        combThick = combThick,
        showPath = showPath,
        pathNumbers = pathNumbers,
        pathWidth = pathWidth,
        plotFit = plotFit,
        showPlotGuide = showPlotGuide)

    analysis <- plainCfaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

